for m,element in enumerate(['斩击','突击','坏击','火焰','冰冻','电击','疾风','光','暗','万能'],69):
    TEXT[m]=[f'那个敌人似乎弱于{element}属性。' if m==70 else f'那个敌人的弱点，\n似乎是{element}属性。']
DUMMY={'ダミーだよ','ダミーのまま入れ込む'}

def main():
    TEXT[102][0]='哎呀，敌人逃了！'
    TEXT[149][0]='有趣的敌人……若让西奥多看到……\n呵呵……真有趣……然后……嘀咕……'
    target=ROOT/'translation/batches/395_margaret_completion.generated.json';assert not target.exists()
    sources=defaultdict(list);seen=set()
    for r in read(ROOT/'translation/catalog.working.json'):
        if r.get('translation') or not r['source'].startswith('export_dlc/0007/battle/support/'):continue
        m=int(re.search(r'_\((\d+)\)',r['source'])[1]);i=r['message_index'];j=r['line_index']
        if m<69 or TOKEN.sub('',r['original']).strip() in DUMMY:continue
        assert j==0
        if m==181:
            name=NAMES[IDS.index(i)]
            body=(f'请留意{name}的倒计时。' if i==2 else f'{name}的倒计时\n已经到１了。')
            if i in (6,9,16,17,19):body=f'{name}的倒计时为１。'
            if i in (0,20):body=f'{name}，倒计时到１了。\n请小心。'
            if i==11:body=f'请留意{name}的倒计时。\n已经到１了。'
        else:body=TEXT[m][i]
        body+='\n';old=r['original'];a=TOKEN.sub('',old).splitlines();b=body.splitlines()
        assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(m,i,max(map(len,b)),max(map(len,a)))
        nums=lambda t:Counter(re.findall(r'\d+',unicodedata.normalize('NFKC',TOKEN.sub('',t))))
        assert nums(old)==nums(body),(m,i)
        doc=read(ROOT/r['source']);sources[r['source']].append([i,j,doc['texts'][i]['id'],body]);seen.add((m,i))
    assert len(seen)==138,len(seen)
    write(target,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['玛格丽特全部剩余138页非占位战斗导航；保留克洛诺斯译名。','保留弱点属性、誓言禁令、蜘蛛脚独立复活时间及倒计时数字；尚未运行测试。']))
    print('Margaret completion:',len(seen))

if __name__=='__main__':main()
